//! `Item.registerItems` as data: every item, block items first (by block id), then the numbered
//! items. Values follow the constructors: `ItemTool`/`ItemSword`/`ItemHoe` take stack size 1 and
//! `ToolMaterial.getMaxUses()`, `ItemArmor` takes `ArmorMaterial.getDurability(slot)`, and the
//! `setMaxStackSize`/`setHasSubtypes`/`setContainerItem` calls in `registerItems` are applied.

use crate::ids::{block, item};
use crate::registry::{ItemDef, Kind, Names};
use crate::tools::{ArmorMaterial, ArmorSlot, ToolClass, ToolMaterial};

/// `BlockPlanks.EnumType` translation keys, by metadata.
pub const WOOD: [&str; 6] = ["oak", "spruce", "birch", "jungle", "acacia", "big_oak"];

#[allow(clippy::too_many_arguments)]
const fn def(
    id: u16,
    name: &'static str,
    class: &'static str,
    key: &'static str,
    max_stack: i32,
    max_damage: i32,
    has_subtypes: bool,
    container: u16,
    kind: Kind,
) -> ItemDef {
    ItemDef { id, name, class, key, max_stack, max_damage, has_subtypes, container, kind }
}

